{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "Is the objective to maximize total profit (revenue minus raw material cost minus operating costs)?",
    "Are the \"Operating Costs at Full Capacity\" figures fixed costs that are incurred whenever any production is assigned to that machine, or are they variable costs proportional to the machine's usage?"
  ],
  "rationale": "The response contains two semantically independent questions: one confirming the objective function and another clarifying the nature of the operating costs (fixed vs. variable)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any demand constraints or minimum production requirements for each product, or is the only limit on how much of each product to produce the machine capacity?"
  ],
  "rationale": "The response asks a single clarification question regarding the nature of production limits (demand/minimums vs. capacity only)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
